window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2ea957b515b24d98"]={"versions": [{"id": "FIG-2ea957b515b24d98", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Auszug aus dem AUTOSAR Adaptive Platform Metamodell / Manifest-Modell).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Zuordnung von Service-Instanzen (<code>AdaptivePlatformServiceInstance</code>) zu einer physischen/logischen Maschine bzw. deren Netzwerkschnittstellen (<code>CommunicationConnector</code>). Es bildet das Bindeglied zwischen softwareseitigem Service-Design/Deployment und der hardwarenahen Netzwerktopologie (Machine/MachineDesign) im Rahmen des <em>Execution Manifests</em> bzw. <em>Service Instance Manifests</em>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>Machine</code></strong> <em>(Spezialisierung von <code>ARElement</code>, <code>AtpStructureElement</code>)</em></li>\n<li>Repräsentiert die konkrete Laufzeitumgebung/Rechnerinstanz (Hardware + OS/Hypervisor).</li>\n<li>Attribut: <code>trustedPlatformExecutableLaunchBehavior: TrustedPlatformExecutableLaunchBehaviorEnum [0..1]</code> – Steuert das Startverhalten vertrauenswürdiger Executables auf der Plattform.</li>\n<li>Assoziation: Referenziert <code>0..1</code> Instanzen von <code>MachineDesign</code> über die Rolle <code>+machineDesign</code>.</li>\n<li><strong><code>MachineDesign</code></strong> <em>(Spezialisierung von <code>AtpStructureElement</code>, <code>FibexElement</code>)</em></li>\n<li>Abstrakte Netzwerksicht der Maschine im Kommunikationscluster (FIBEX-Kontext).</li>\n<li>Attribute:</li>\n<li><code>accessControl: AccessControlEnum [0..1]</code> – Sicherheits-/Zugriffssteuerungsrichtlinie.</li>\n<li><code>pncPrepareSleepTimer: TimeValue [0..1]</code> – Timeout für Partial Network Cluster (PNC) Sleep-Vorbereitung.</li>\n<li><code>pnResetTimer: TimeValue [0..1]</code> – Reset-Timer für Partial Networking.</li>\n<li><strong><code>CommunicationConnector</code></strong> <em>(Spezialisierung von <code>Identifiable</code>)</em></li>\n<li>Physischer/logischer Netzwerkanschluss (z. B. Ethernet-Interface) der Maschine.</li>\n<li>Attribute:</li>\n<li><code>createEcuWakeupSource: Boolean [0..1]</code> – Definiert, ob der Connector eine ECU-Wakeup-Quelle darstellt.</li>\n<li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code> – Maskenfilter-Array für PNC-Routing/Filterung.</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code></strong> <em>(Spezialisierung von <code>UploadablePackageElement</code>)</em></li>\n<li>Zentrales Mapping-Element zur Bindung von Service-Instanzen an Netzwerk-Endpunkte.</li>\n<li><strong><code>AdaptivePlatformServiceInstance</code></strong> <em>(Spezialisierung von <code>UploadablePackageElement</code>)</em></li>\n<li>Instanziierter Service (Provided oder Consumed Service Instance) der AUTOSAR Adaptive Platform.</li>\n<li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(Spezialisierung von <code>UploadablePackageElement</code>)</em></li>\n<li>Protokollspezifische Serialisierungs- und Transportdefinition des Service-Interface (z. B. SOME/IP, IPC, DDS Deployment).</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen, Stereotypen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>MachineDesign</code> $\\blacklozenge\\xrightarrow{\\text{«atpSplitable»}}$ <code>CommunicationConnector</code>:</strong></li>\n<li>Komposition mit Stereotyp <code>«atpSplitable»</code> (Aggregationsrolle <code>+communicationConnector</code>, Multiplizität <code>0..*</code>). Erlaubt die Aufteilung der Connector-Definition über mehrere ARXML-Dateien/Pakete.</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code> $\\xrightarrow{}$ <code>CommunicationConnector</code>:</strong></li>\n<li>Unidirektionale Assoziation (<code>+communicationConnector</code>, Multiplizität <code>0..1</code>). Weist den gemappten Service-Instanzen einen konkreten Netzwerk-Konnektor (IP-Stack, Interface) zu.</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code> $\\xrightarrow{}$ <code>AdaptivePlatformServiceInstance</code>:</strong></li>\n<li>Unidirektionale Assoziation (<code>+serviceInstance</code>, Multiplizität <code>0..*</code>). Gruppiert eine oder mehrere Service-Instanzen auf dasselbe Interface-Mapping.</li>\n<li><strong><code>AdaptivePlatformServiceInstance</code> $\\xrightarrow{}$ <code>ServiceInterfaceDeployment</code>:</strong></li>\n<li>Unidirektionale Assoziation (<code>+serviceInterfaceDeployment</code>, Multiplizität <code>0..1</code>). Referenziert das konkrete Binding/Deployment für die Serialisierung und Adressierung.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammcharakter:</strong> Rein statisches Konfigurations- und Metamodell; keine Laufzeit-Zustände oder Callbacks direkt modelliert.</li>\n<li><strong>Laufzeit-Implikation (ara::com / Service Discovery & Binding):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung/Start:</strong> Der Kommunikations-Stack (SOME/IP-Daemon / Middleware) wertet das Manifest aus.</li>\n<li><strong>Netzwerk-Bindung:</strong> Über den <code>CommunicationConnector</code> werden IP-Adresse, VLAN, UDP/TCP-Portranges und MAC-Adresse an die <code>AdaptivePlatformServiceInstance</code> gebunden.</li>\n<li><strong>Service Discovery (SD):</strong> Offer-/Find-Service-Nachrichten werden über den zugeordneten Connector gesendet/empfangen.</li>\n<li><strong>PNC / Power Management:</strong> Bei vorhandenem <code>pncFilterArrayMask</code> und gesetzten Timern (<code>pncPrepareSleepTimer</code>, <code>pnResetTimer</code>) triggert eingehender Netzwerkverkehr auf diesem Connector das Aufwecken bzw. verhindert das Schlafenlegen des entsprechenden Teilnetzes.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Generierung & Toolchain:</strong> Das <code>ServiceInstanceToMachineMapping</code> ist essenzieller Input für Generatoren von <code>ara::com</code>-Laufzeitumgebungen und SOME/IP-Daemon-Konfigurationen (<code>someipd-posix.json</code> o. ä.). Ohne dieses Mapping kann die Middleware einen Service nicht an eine physische Netzwerkschnittstelle oder IP-Adresse binden.</li>\n<li><strong>Entkopplung Applikation vs. Plattform:</strong></li>\n<li>Der Applikationscode (<code>ara::com</code>-Schnittstelle) bleibt agnostisch gegenüber der Ziel-Maschine und den physikalischen Connectors.</li>\n<li>Erst bei Systemintegration und Deployment wird über das <code>ServiceInstanceToMachineMapping</code> festgelegt, über welches Interface (z. B. <code>eth0</code> vs. internes IPC) die Service-Kommunikation geroutet wird.</li>\n<li><strong>Kardinalitäts-Restriktion:</strong></li>\n<li>Ein <code>ServiceInstanceToMachineMapping</code> adressiert maximal genau einen <code>CommunicationConnector</code> (<code>0..1</code>). Soll dieselbe Service-Instanz über mehrere Schnittstellen angeboten/konsumiert werden, sind separate Mappings bzw. spezifische Proxy/Skeleton-Deployments erforderlich.</li>\n<li><strong>Partial Networking (PNC):</strong> Werden PNC-Filter (<code>pncFilterArrayMask</code>) genutzt, muss sichergestellt sein, dass der Treiber bzw. Network-Management-Stack (<code>ara::nm</code>) die Wakeup- und Filter-Konfigurationen synchron mit der Switch-/Controller-Hardware initialisiert.</li>\n</ul>"}, {"id": "FIG-fc8d0cf461584413", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Auszug aus dem AUTOSAR Adaptive Platform Metamodell / Manifest-Modell).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Zuordnung von Service-Instanzen (<code>AdaptivePlatformServiceInstance</code>) zu einer physischen/logischen Maschine bzw. deren Netzwerkschnittstellen (<code>CommunicationConnector</code>). Es bildet das Bindeglied zwischen softwareseitigem Service-Design/Deployment und der hardwarenahen Netzwerktopologie (Machine/MachineDesign) im Rahmen des <em>Execution Manifests</em> bzw. <em>Service Instance Manifests</em>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>Machine</code></strong> <em>(Spezialisierung von <code>AtpStructureElement</code>, <code>UploadableDeploymentElement</code>)</em></li>\n<li>Repräsentiert die konkrete Laufzeitumgebung/Rechnerinstanz (Hardware + OS/Hypervisor).</li>\n<li>Attribut: <code>trustedPlatformExecutableLaunchBehavior: TrustedPlatformExecutableLaunchBehaviorEnum [0..1]</code> – Steuert das Startverhalten vertrauenswürdiger Executables auf der Plattform.</li>\n<li>Assoziation: Referenziert <code>0..1</code> Instanzen von <code>MachineDesign</code> über die Rolle <code>+machineDesign</code>.</li>\n<li><strong><code>MachineDesign</code></strong> <em>(Spezialisierung von <code>AtpStructureElement</code>, <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em></li>\n<li>Abstrakte Netzwerksicht der Maschine im Kommunikationscluster (FIBEX-Kontext).</li>\n<li>Attribute:</li>\n<li><code>accessControl: AccessControlEnum [0..1]</code> – Sicherheits-/Zugriffssteuerungsrichtlinie.</li>\n<li><code>pncPrepareSleepTimer: TimeValue [0..1]</code> – Timeout für Partial Network Cluster (PNC) Sleep-Vorbereitung.</li>\n<li><code>pnResetTimer: TimeValue [0..1]</code> – Reset-Timer für Partial Networking.</li>\n<li><strong><code>CommunicationConnector</code></strong> <em>(Spezialisierung von <code>Identifiable</code>)</em></li>\n<li>Physischer/logischer Netzwerkanschluss (z. B. Ethernet-Interface) der Maschine.</li>\n<li>Attribute:</li>\n<li><code>createEcuWakeupSource: Boolean [0..1]</code> – Definiert, ob der Connector eine ECU-Wakeup-Quelle darstellt.</li>\n<li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code> – Maskenfilter-Array für PNC-Routing/Filterung.</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code></strong> <em>(Spezialisierung von <code>UploadableDesignElement</code>)</em></li>\n<li>Zentrales Mapping-Element zur Bindung von Service-Instanzen an Netzwerk-Endpunkte.</li>\n<li><strong><code>AdaptivePlatformServiceInstance</code></strong> <em>(Spezialisierung von <code>UploadableDesignElement</code>)</em></li>\n<li>Instanziierter Service (Provided oder Consumed Service Instance) der AUTOSAR Adaptive Platform.</li>\n<li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(Spezialisierung von <code>UploadableDesignElement</code>)</em></li>\n<li>Protokollspezifische Serialisierungs- und Transportdefinition des Service-Interface (z. B. SOME/IP, IPC, DDS Deployment).</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen, Stereotypen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>MachineDesign</code> $\\blacklozenge\\xrightarrow{\\text{«atpSplitable»}}$ <code>CommunicationConnector</code>:</strong></li>\n<li>Komposition mit Stereotyp <code>«atpSplitable»</code> (Aggregationsrolle <code>+communicationConnector</code>, Multiplizität <code>0..*</code>). Erlaubt die Aufteilung der Connector-Definition über mehrere ARXML-Dateien/Pakete.</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code> $\\xrightarrow{}$ <code>CommunicationConnector</code>:</strong></li>\n<li>Unidirektionale Assoziation (<code>+communicationConnector</code>, Multiplizität <code>0..1</code>). Weist den gemappten Service-Instanzen einen konkreten Netzwerk-Konnektor (IP-Stack, Interface) zu.</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code> $\\xrightarrow{}$ <code>AdaptivePlatformServiceInstance</code>:</strong></li>\n<li>Unidirektionale Assoziation (<code>+serviceInstance</code>, Multiplizität <code>0..*</code>). Gruppiert eine oder mehrere Service-Instanzen auf dasselbe Interface-Mapping.</li>\n<li><strong><code>AdaptivePlatformServiceInstance</code> $\\xrightarrow{}$ <code>ServiceInterfaceDeployment</code>:</strong></li>\n<li>Unidirektionale Assoziation (<code>+serviceInterfaceDeployment</code>, Multiplizität <code>0..1</code>). Bindet die Service-Instanz an ihre konkrete Schnittstellen-Bereitstellungsspezifikation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammcharakter:</strong> Rein statisches Konfigurations- und Metamodell; keine Laufzeit-Zustände oder Callbacks direkt modelliert.</li>\n<li><strong>Laufzeit-Implikation (ara::com / Service Discovery & Binding):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung/Start:</strong> Der Kommunikations-Stack (SOME/IP-Daemon / Middleware) wertet das Manifest aus.</li>\n<li><strong>Netzwerk-Bindung:</strong> Über den <code>CommunicationConnector</code> werden IP-Adresse, VLAN, UDP/TCP-Portranges und MAC-Adresse an die <code>AdaptivePlatformServiceInstance</code> gebunden.</li>\n<li><strong>Service Discovery (SD):</strong> Offer-/Find-Service-Nachrichten werden über den zugeordneten Connector gesendet/empfangen.</li>\n<li><strong>PNC / Power Management:</strong> Bei vorhandenem <code>pncFilterArrayMask</code> und gesetzten Timern (<code>pncPrepareSleepTimer</code>, <code>pnResetTimer</code>) triggert eingehender Netzwerkverkehr auf diesem Connector das Aufwecken bzw. verhindert das Schlafenlegen des entsprechenden Teilnetzes.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Manifest-Strukturierung:</strong> Die Differenzierung der Generalisierungen trennt Design-Artefakte (<code>UploadableDesignElement</code>) wie <code>MachineDesign</code>, <code>AdaptivePlatformServiceInstance</code>, <code>ServiceInterfaceDeployment</code> und <code>ServiceInstanceToMachineMapping</code> formal von Deployment-Artefakten (<code>UploadableDeploymentElement</code>) wie <code>Machine</code>.</li>\n<li><strong>Kardinalitäten und Multiplizitäten:</strong></li>\n<li>Die Multiplizität <code>0..*</code> für <code>+serviceInstance</code> erlaubt die gemeinsame Zuweisung mehrerer Service-Instanzen zu einem <code>CommunicationConnector</code> über ein einzelnes Mapping-Element.</li>\n<li>Die Kardinalität <code>0..1</code> bei <code>+communicationConnector</code> ermöglicht die Spezifikation maschineninterner Service-Instanzen (z. B. für maschinenlokales IPC), die keinen externen Netzwerkanschluss erfordern.</li>\n<li><strong>Modellierungsrichtlinien:</strong></li>\n<li>Das Stereotyp <code>«atpSplitable»</code> an der Komposition von <code>CommunicationConnector</code> erlaubt die Verteilung der physischen Schnittstellendefinitionen über mehrere Manifest-Dateien.</li>\n<li>Bei der Codegenerierung für die Middleware (z. B. <code>ara::com</code>) ist das Vorhandensein des Mappings zwingend erforderlich, um Netzwerk-Sockets bzw. Service Discovery (SOME/IP SD) an die korrekte Netzwerkschnittstelle zu binden.</li>\n</ul>"}, {"id": "FIG-f47547993e1eed6f", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Auszug aus dem AUTOSAR Adaptive Platform Metamodell / Manifest-Modell).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Zuordnung von Service-Instanzen (<code>AdaptivePlatformServiceInstance</code>) zu einer physischen/logischen Maschine bzw. deren Netzwerkschnittstellen (<code>CommunicationConnector</code>). Es bildet das Bindeglied zwischen softwareseitigem Service-Design/Deployment und der hardwarenahen Netzwerktopologie (Machine/MachineDesign) im Rahmen des <em>Execution Manifests</em> bzw. <em>Service Instance Manifests</em>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>Machine</code></strong> <em>(Spezialisierung von <code>AtpStructureElement</code>, <code>UploadableDeploymentElement</code>)</em></li>\n<li>Repräsentiert die konkrete Laufzeitumgebung/Rechnerinstanz (Hardware + OS/Hypervisor).</li>\n<li>Attribut: <code>trustedPlatformExecutableLaunchBehavior: TrustedPlatformExecutableLaunchBehaviorEnum [0..1]</code> – Steuert das Startverhalten vertrauenswürdiger Executables auf der Plattform.</li>\n<li>Assoziation: Referenziert <code>0..1</code> Instanzen von <code>MachineDesign</code> über die Rolle <code>+machineDesign</code>.</li>\n<li><strong><code>MachineDesign</code></strong> <em>(Spezialisierung von <code>AtpStructureElement</code>, <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em></li>\n<li>Abstrakte Netzwerksicht der Maschine im Kommunikationscluster (FIBEX-Kontext).</li>\n<li>Attribute:</li>\n<li><code>accessControl: AccessControlEnum [0..1]</code> – Sicherheits-/Zugriffssteuerungsrichtlinie.</li>\n<li><code>pncPrepareSleepTimer: TimeValue [0..1]</code> – Timeout für Partial Network Cluster (PNC) Sleep-Vorbereitung.</li>\n<li><code>pnResetTimer: TimeValue [0..1]</code> – Reset-Timer für Partial Networking.</li>\n<li><strong><code>CommunicationConnector</code></strong> <em>(Spezialisierung von <code>Identifiable</code>)</em></li>\n<li>Physischer/logischer Netzwerkanschluss (z. B. Ethernet-Interface) der Maschine.</li>\n<li>Attribute:</li>\n<li><code>createEcuWakeupSource: Boolean [0..1]</code> – Definiert, ob der Connector eine ECU-Wakeup-Quelle darstellt.</li>\n<li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code> – Maskenfilter-Array für PNC-Routing/Filterung.</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code></strong> <em>(Spezialisierung von <code>UploadableDesignElement</code>)</em></li>\n<li>Zentrales Mapping-Element zur Bindung von Service-Instanzen an Netzwerk-Endpunkte.</li>\n<li><strong><code>AdaptivePlatformServiceInstance</code></strong> <em>(Spezialisierung von <code>UploadableDesignElement</code>)</em></li>\n<li>Instanziierter Service (Provided oder Consumed Service Instance) der AUTOSAR Adaptive Platform.</li>\n<li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(Spezialisierung von <code>UploadableDesignElement</code>)</em></li>\n<li>Protokollspezifische Serialisierungs- und Transportdefinition des Service-Interface (z. B. SOME/IP, IPC, DDS Deployment).</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen, Stereotypen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>MachineDesign</code> $\\blacklozenge\\xrightarrow{\\text{«atpSplitable»}}$ <code>CommunicationConnector</code>:</strong></li>\n<li>Komposition mit Stereotyp <code>«atpSplitable»</code> (Aggregationsrolle <code>+communicationConnector</code>, Multiplizität <code>0..*</code>). Erlaubt die Aufteilung der Connector-Definition über mehrere ARXML-Dateien/Pakete.</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code> $\\xrightarrow{}$ <code>CommunicationConnector</code>:</strong></li>\n<li>Unidirektionale Assoziation (<code>+communicationConnector</code>, Multiplizität <code>0..1</code>). Weist den gemappten Service-Instanzen einen konkreten Netzwerk-Konnektor (IP-Stack, Interface) zu.</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code> $\\xrightarrow{}$ <code>AdaptivePlatformServiceInstance</code>:</strong></li>\n<li>Unidirektionale Assoziation (<code>+serviceInstance</code>, Multiplizität <code>0..*</code>). Gruppiert eine oder mehrere Service-Instanzen auf dasselbe Interface-Mapping.</li>\n<li><strong><code>AdaptivePlatformServiceInstance</code> $\\xrightarrow{}$ <code>ServiceInterfaceDeployment</code>:</strong></li>\n<li>Unidirektionale Assoziation (<code>+serviceInterfaceDeployment</code>, Multiplizität <code>0..1</code>). Bindet die Service-Instanz an ihre konkrete Schnittstellen-Bereitstellungsspezifikation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammcharakter:</strong> Rein statisches Konfigurations- und Metamodell; keine Laufzeit-Zustände oder Callbacks direkt modelliert.</li>\n<li><strong>Laufzeit-Implikation (ara::com / Service Discovery & Binding):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung/Start:</strong> Der Kommunikations-Stack (SOME/IP-Daemon / Middleware) wertet das Manifest aus.</li>\n<li><strong>Netzwerk-Bindung:</strong> Über den <code>CommunicationConnector</code> werden IP-Adresse, VLAN, UDP/TCP-Portranges und MAC-Adresse an die <code>AdaptivePlatformServiceInstance</code> gebunden.</li>\n<li><strong>Service Discovery (SD):</strong> Offer-/Find-Service-Nachrichten werden über den zugeordneten Connector gesendet/empfangen.</li>\n<li><strong>PNC / Power Management:</strong> Bei vorhandenem <code>pncFilterArrayMask</code> und gesetzten Timern (<code>pncPrepareSleepTimer</code>, <code>pnResetTimer</code>) triggert eingehender Netzwerkverkehr auf diesem Connector das Aufwecken bzw. verhindert das Schlafenlegen des entsprechenden Teilnetzes.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Manifest-Strukturierung:</strong> Die Differenzierung der Generalisierungen trennt Design-Artefakte (<code>UploadableDesignElement</code>) wie <code>MachineDesign</code>, <code>AdaptivePlatformServiceInstance</code>, <code>ServiceInterfaceDeployment</code> und <code>ServiceInstanceToMachineMapping</code> formal von Deployment-Artefakten (<code>UploadableDeploymentElement</code>) wie <code>Machine</code>.</li>\n<li><strong>Kardinalitäten und Multiplizitäten:</strong></li>\n<li>Die Multiplizität <code>0..*</code> für <code>+serviceInstance</code> erlaubt die gemeinsame Zuweisung mehrerer Service-Instanzen zu einem <code>CommunicationConnector</code> über ein einzelnes Mapping-Element.</li>\n<li>Die Kardinalität <code>0..1</code> bei <code>+communicationConnector</code> ermöglicht die Spezifikation maschineninterner Service-Instanzen (z. B. für maschinenlokales IPC), die keinen externen Netzwerkanschluss erfordern.</li>\n<li><strong>Modellierungsrichtlinien:</strong></li>\n<li>Das Stereotyp <code>«atpSplitable»</code> an der Komposition von <code>CommunicationConnector</code> erlaubt die Verteilung der physischen Schnittstellendefinitionen über mehrere Manifest-Dateien.</li>\n<li>Bei der Codegenerierung für die Middleware (z. B. <code>ara::com</code>) ist das Vorhandensein des Mappings zwingend erforderlich, um Netzwerk-Sockets bzw. Service Discovery (SOME/IP SD) an die korrekte Netzwerkschnittstelle zu binden.</li>\n</ul>"}, {"id": "FIG-431810d7f8d99675", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Auszug aus dem AUTOSAR Adaptive Platform Metamodell / Manifest-Modell).</li>\n<li><strong>Technischer Zweck:</strong> Definition der Zuordnung von Service-Instanzen (<code>AdaptivePlatformServiceInstance</code>) zu einer physischen/logischen Maschine bzw. deren Netzwerkschnittstellen (<code>CommunicationConnector</code>). Es bildet das Bindeglied zwischen softwareseitigem Service-Design/Deployment und der hardwarenahen Netzwerktopologie (Machine/MachineDesign) im Rahmen des <em>Execution Manifests</em> bzw. <em>Service Instance Manifests</em>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metamodell-Klassen & Attribute</p>\n<ul class=\"fig-list\">\n<li><strong><code>Machine</code></strong> <em>(Spezialisierung von <code>AtpStructureElement</code>, <code>UploadableDeploymentElement</code>)</em></li>\n<li>Repräsentiert die konkrete Laufzeitumgebung/Rechnerinstanz (Hardware + OS/Hypervisor).</li>\n<li>Attribut: <code>trustedPlatformExecutableLaunchBehavior: TrustedPlatformExecutableLaunchBehaviorEnum [0..1]</code> – Steuert das Startverhalten vertrauenswürdiger Executables auf der Plattform.</li>\n<li>Assoziation: Referenziert <code>0..1</code> Instanzen von <code>MachineDesign</code> über die Rolle <code>+machineDesign</code>.</li>\n<li><strong><code>MachineDesign</code></strong> <em>(Spezialisierung von <code>AtpStructureElement</code>, <code>FibexElement</code>, <code>UploadableDesignElement</code>)</em></li>\n<li>Abstrakte Netzwerksicht der Maschine im Kommunikationscluster (FIBEX-Kontext).</li>\n<li>Attribute:</li>\n<li><code>accessControl: AccessControlEnum [0..1]</code> – Sicherheits-/Zugriffssteuerungsrichtlinie.</li>\n<li><code>pncPrepareSleepTimer: TimeValue [0..1]</code> – Timeout für Partial Network Cluster (PNC) Sleep-Vorbereitung.</li>\n<li><code>pnResetTimer: TimeValue [0..1]</code> – Reset-Timer für Partial Networking.</li>\n<li><strong><code>CommunicationConnector</code></strong> <em>(Spezialisierung von <code>Identifiable</code>)</em></li>\n<li>Physischer/logischer Netzwerkanschluss (z. B. Ethernet-Interface) der Maschine.</li>\n<li>Attribute:</li>\n<li><code>createEcuWakeupSource: Boolean [0..1]</code> – Definiert, ob der Connector eine ECU-Wakeup-Quelle darstellt.</li>\n<li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code> – Maskenfilter-Array für PNC-Routing/Filterung.</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code></strong> <em>(Spezialisierung von <code>UploadableDesignElement</code>)</em></li>\n<li>Zentrales Mapping-Element zur Bindung von Service-Instanzen an Netzwerk-Endpunkte.</li>\n<li><strong><code>AdaptivePlatformServiceInstance</code></strong> <em>(Spezialisierung von <code>UploadableDesignElement</code>)</em></li>\n<li>Instanziierter Service (Provided oder Consumed Service Instance) der AUTOSAR Adaptive Platform.</li>\n<li><strong><code>ServiceInterfaceDeployment</code></strong> <em>(Spezialisierung von <code>UploadableDesignElement</code>)</em></li>\n<li>Protokollspezifische Serialisierungs- und Transportdefinition des Service-Interface (z. B. SOME/IP, IPC, DDS Deployment).</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen, Stereotypen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>MachineDesign</code> $\\blacklozenge\\xrightarrow{\\text{«atpSplitable»}}$ <code>CommunicationConnector</code>:</strong></li>\n<li>Komposition mit Stereotyp <code>«atpSplitable»</code> (Aggregationsrolle <code>+communicationConnector</code>, Multiplizität <code>0..*</code>). Erlaubt die Aufteilung der Connector-Definition über mehrere ARXML-Dateien/Pakete.</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code> $\\xrightarrow{}$ <code>CommunicationConnector</code>:</strong></li>\n<li>Unidirektionale Assoziation (<code>+communicationConnector</code>, Multiplizität <code>0..1</code>). Weist den gemappten Service-Instanzen einen konkreten Netzwerk-Konnektor (IP-Stack, Interface) zu.</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code> $\\xrightarrow{}$ <code>AdaptivePlatformServiceInstance</code>:</strong></li>\n<li>Unidirektionale Assoziation (<code>+serviceInstance</code>, Multiplizität <code>0..*</code>). Gruppiert eine oder mehrere Service-Instanzen auf dasselbe Interface-Mapping.</li>\n<li><strong><code>AdaptivePlatformServiceInstance</code> $\\xrightarrow{}$ <code>ServiceInterfaceDeployment</code>:</strong></li>\n<li>Unidirektionale Assoziation (<code>+serviceInterfaceDeployment</code>, Multiplizität <code>0..1</code>). Bindet die Service-Instanz an ihre konkrete Schnittstellen-Bereitstellungsspezifikation.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammcharakter:</strong> Rein statisches Konfigurations- und Metamodell; keine Laufzeit-Zustände oder Callbacks direkt modelliert.</li>\n<li><strong>Laufzeit-Implikation (ara::com / Service Discovery & Binding):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung/Start:</strong> Der Kommunikations-Stack (SOME/IP-Daemon / Middleware) wertet das Manifest aus.</li>\n<li><strong>Netzwerk-Bindung:</strong> Über den <code>CommunicationConnector</code> werden IP-Adresse, VLAN, UDP/TCP-Portranges und MAC-Adresse an die <code>AdaptivePlatformServiceInstance</code> gebunden.</li>\n<li><strong>Service Discovery (SD):</strong> Offer-/Find-Service-Nachrichten werden über den zugeordneten Connector gesendet/empfangen.</li>\n<li><strong>PNC / Power Management:</strong> Bei vorhandenem <code>pncFilterArrayMask</code> und gesetzten Timern (<code>pncPrepareSleepTimer</code>, <code>pnResetTimer</code>) triggert eingehender Netzwerkverkehr auf diesem Connector das Aufwecken bzw. verhindert das Schlafenlegen des entsprechenden Teilnetzes.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Manifest-Strukturierung:</strong> Die Differenzierung der Generalisierungen trennt Design-Artefakte (<code>UploadableDesignElement</code>) wie <code>MachineDesign</code>, <code>AdaptivePlatformServiceInstance</code>, <code>ServiceInterfaceDeployment</code> und <code>ServiceInstanceToMachineMapping</code> formal von Deployment-Artefakten (<code>UploadableDeploymentElement</code>) wie <code>Machine</code>.</li>\n<li><strong>Kardinalitäten und Multiplizitäten:</strong></li>\n<li>Die Multiplizität <code>0..*</code> für <code>+serviceInstance</code> erlaubt die gemeinsame Zuweisung mehrerer Service-Instanzen zu einem <code>CommunicationConnector</code> über ein einzelnes Mapping-Element.</li>\n<li>Die Kardinalität <code>0..1</code> bei <code>+communicationConnector</code> ermöglicht die Spezifikation maschineninterner Service-Instanzen (z. B. für maschinenlokales IPC), die keinen externen Netzwerkanschluss erfordern.</li>\n<li><strong>Modellierungsrichtlinien:</strong></li>\n<li>Das Stereotyp <code>«atpSplitable»</code> an der Komposition von <code>CommunicationConnector</code> erlaubt die Verteilung der physischen Schnittstellendefinitionen über mehrere Manifest-Dateien.</li>\n<li>Bei der Codegenerierung für die Middleware (z. B. <code>ara::com</code>) ist das Vorhandensein des Mappings zwingend erforderlich, um Netzwerk-Sockets bzw. Service Discovery (SOME/IP SD) an die korrekte Netzwerkschnittstelle zu binden.</li>\n</ul>"}], "trans": [{"from": "FIG-2ea957b515b24d98", "to": "FIG-fc8d0cf461584413", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong><code>Machine</code>:</strong> Generalisierung von <code>ARElement</code> auf <code>UploadableDeploymentElement</code> geändert (unter Beibehaltung von <code>AtpStructureElement</code>).</li>\n<li><strong><code>MachineDesign</code>:</strong> Zusätzliche Generalisierung <code>UploadableDesignElement</code> ergänzt (neben <code>AtpStructureElement</code> und <code>FibexElement</code>).</li>\n<li><strong><code>ServiceInstanceToMachineMapping</code>:</strong> Generalisierung von <code>UploadablePackageElement</code> auf <code>UploadableDesignElement</code> geändert.</li>\n<li><strong><code>AdaptivePlatformServiceInstance</code>:</strong> Generalisierung von <code>UploadablePackageElement</code> auf <code>UploadableDesignElement</code> geändert.</li>\n<li><strong><code>ServiceInterfaceDeployment</code>:</strong> Generalisierung von <code>UploadablePackageElement</code> auf <code>UploadableDesignElement</code> geändert.</li>\n</ul>"}, {"from": "FIG-fc8d0cf461584413", "to": "FIG-f47547993e1eed6f", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f47547993e1eed6f", "to": "FIG-431810d7f8d99675", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
